pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score: prioritize tighter fits (smaller post_residual).
    // We add a non-linear weight to post_residual to discourage mid-sized gaps.
    let mut score = (post_residual as f64).powf(1.15);

    if bin_residual == bin_capacity {
        // New bin penalty: dynamic thresholding based on stream progress.
        // As the stream progresses, we become more conservative about opening new bins.
        let new_bin_base = 120.0 + (mean_residual * 1.8);
        score += new_bin_base * (1.0 + progress);
    } else {
        // Lookahead optimization: reward fitting the next item perfectly.
        // We calculate the delta between the post-residual and the next item size.
        if next_item_size > 0 {
            let gap = post_residual as i32 - next_item_size as i32;
            if gap >= 0 {
                // Reward perfect fit or near-perfect fit.
                score -= (45.0 / (1.0 + gap as f64));
            } else {
                // Penalize fragmenting if post_residual is smaller than next_item_size.
                score += (gap.abs() as f64).powf(1.2) * 1.5;
            }
        }

        // Favor bins that are already "locked in" (low fitting_bins_count).
        if fitting_bins_count <= 2 {
            score -= 30.0 * (1.0 - progress);
        }

        // Efficiency refinement: penalize excessive fragmentation in early-mid stages.
        if post_residual < 15 && post_residual > 0 {
            score += 20.0 * (1.0 - progress);
        }
    }

    // Global constraint: ensure we don't end up with too many open bins.
    // If open_bins_count is high, increase the cost of opening new ones or selecting sparse ones.
    score += (open_bins_count as f64 * 0.5) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // Penalize large post_residual values quadratically to avoid fragmentation.
    let mut score = post * post;

    // Lookahead coupling: If a next item exists, penalize bins that leave insufficient space for it.
    // We want to keep space open if the next item is large.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32) as f64;
        if diff < 0.0 {
            // Strong penalty for creating a bin that cannot fit the next item if we have choices.
            score += 5000.0 * (1.0 + diff.abs());
        } else {
            // Reward bins that leave exactly enough space for the next item (tight packing).
            score -= 1000.0 / (1.0 + diff);
        }
    }

    // Progression coupling: As the stream nears completion, become more aggressive 
    // at packing tightly to close open bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // High priority to finish off a bin if it's the only one that fits.
        score -= 2000.0 * progress;
    }

    // Penalty for opening a new bin:
    // Only open a new bin if the current residual is high and we are early in the stream.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin.
        score += 2500.0;
        // As we progress, opening new bins becomes increasingly penalized to force packing into existing ones.
        score += 3000.0 * progress;
    }

    // Balance against mean_residual:
    // Encourage bins that align with the global average to keep entropy low.
    let residual_deviation = (post - mean_residual).abs();
    score += 50.0 * residual_deviation;

    score
}

