pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "dead space" that cannot fit common small items (e.g., < 20).
    // If post_residual is in a range that is hard to fill, penalize it.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0;
    }

    // Lookahead logic: if the next item can fit in the current post_residual, 
    // prioritize this bin heavily to avoid fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // Harmonic/Modular pressure: favor residuals that align with common multiples 
    // of the capacity to keep bin space utilization homogeneous.
    let residual_mod = (post_residual % 25) as f64;
    score += residual_mod * 0.5;

    // If this is the only bin that can fit the item, prioritize it to avoid 
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Strategy for opening a new bin:
    // Only open a new bin if the current bin's post_residual is highly inefficient
    // (e.g., very small and not fitting the next item).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // High penalty for opening a new bin unless existing bins are very full.
            score = 60.0 + (mean_residual * 0.5);
        }
    }

    // Progression weighting: as the stream nears the end, be more aggressive 
    // with packing to reduce the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score is the remaining space; we want to minimize this (Best Fit).
    let mut score = post_residual as f64;

    // Phase-based intensity: Scale the impact of residual space as the stream progresses.
    let progress = step_index as f64 / total_items as f64;

    // Penalize "slivers" (dead space < 15) more aggressively as we near the end of the stream
    // to force tighter packing when opportunities decrease.
    if post_residual > 0 && post_residual < 15 {
        score += 55.0 * (1.0 + progress);
    }

    // Lookahead refinement: If the next item fits, we grant a larger discount.
    // We scale this discount based on the 'mean_residual' to avoid over-packing bins
    // that are already statistically likely to be full.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_bonus = 35.0 * (1.0 - (mean_residual / bin_capacity as f64));
        score -= lookahead_bonus;
    }

    // Dynamic density pressure: If we have many open bins, we become more conservative
    // about opening new ones, effectively increasing the cost of a new bin.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = -10.0; // Must open the first bin
        } else {
            // Threshold for new bin: only if existing bins are too sparse to accommodate future items.
            // We factor in the average residual to estimate if a new bin is actually "cleaner".
            score = 75.0 + (mean_residual * 0.8) - (progress * 20.0);
        }
    } else {
        // If we are forced to fit into a bin (the only one available), reward it 
        // to prevent premature new bin creation.
        if fitting_bins_count == 1 {
            score -= 65.0;
        }
    }

    // Entropy dampening: penalize residuals that are far from the global mean_residual
    // to promote uniform bin usage across the set.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Core objective: Minimize post_residual (Best Fit)
    let mut score = post_residual as f64;

    if bin_residual == bin_capacity {
        // Dynamic threshold for opening new bins:
        // Heavily penalize unless existing bins are saturated (high mean_residual).
        // Scaling with progress allows looser packing early, tighter late.
        score += 135.0 + (mean_residual * 2.2) + (progress * 20.0);
    } else {
        // Lookahead: If next_item_size fits perfectly into the remaining space, 
        // aggressively reward this bin to create a "perfect pair".
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 65.0;
            } else if post_residual > next_item_size {
                // Penalize fragmentation: if post_residual is slightly larger than next,
                // it might be better to save the space for a different item.
                score += (post_residual - next_item_size) as f64 * 0.4;
            }
        }

        // Sliver prevention: penalize residuals that are too small to be useful
        // for most items, but only if we are past the early stage.
        if post_residual > 0 && post_residual < 15 {
            score += 50.0 * (1.0 - (progress * 0.3));
        }

        // Constraint handling: If this is the only bin that can house the current item,
        // it must be prioritized to prevent opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 150.0;
        }

        // Density control: Consolidate items into fewer bins by penalizing 
        // high open_bins_count, forcing the heuristic to favor existing bins.
        if open_bins_count > 5 {
            score += (open_bins_count as f64 * 1.5) - (post_residual as f64 * 0.2);
        }

        // Adaptive packing:
        // Late stage: strongly prefer filling bins to capacity to finalize them.
        if progress > 0.6 {
            score -= (bin_capacity - post_residual) as f64 * 0.35;
        }

        // Variance dampening: Reward filling a bin to a near-perfect state.
        if post_residual < 4 {
            score -= 25.0;
        }
    }

    score
}
